import logging
import queue
import threading

logger = logging.getLogger(__name__)


class _Shutdown:
    """Sentinel pushed onto the queue to tell the worker to stop consuming."""

    def __repr__(self):
        return "<shutdown>"


SHUTDOWN = _Shutdown()


class QueueWorker:
    """Consumes items from a queue on a background thread, one callback per item."""

    def __init__(self, work_queue, handle_item, name="queue-worker"):
        self.work_queue = work_queue
        self.handle_item = handle_item
        self.thread = threading.Thread(target=self._run, name=name, daemon=True)
        self.processed = 0
        self.failed = 0
        self._stopping = threading.Event()

    def start(self):
        self.thread.start()
        return self

    def _run(self):
        while True:
            item = self.work_queue.get()
            try:
                if item is SHUTDOWN:
                    self._stopping.set()
                    logger.debug(
                        "shutdown sentinel received after %d items (%d failed)",
                        self.processed,
                        self.failed,
                    )
                    return
                self.handle_item(item)
                self.processed += 1
            except Exception:
                self.failed += 1
                logger.exception("worker callback failed for item %r", item)
            finally:
                self.work_queue.task_done()

    def submit(self, item):
        if self._stopping.is_set():
            raise RuntimeError("worker is shutting down; item rejected")
        self.work_queue.put(item)

    def drain(self):
        """Block until every item queued so far has been handled."""
        self.work_queue.join()

    def stop(self, timeout=5.0):
        """Queue the sentinel and wait for the thread to finish its current item."""
        if self._stopping.is_set() and not self.thread.is_alive():
            return
        self.work_queue.put(SHUTDOWN)
        self.thread.join(timeout)
        if self.thread.is_alive():
            logger.warning("worker thread did not exit within %.1fs", timeout)

    def __enter__(self):
        return self.start()

    def __exit__(self, exc_type, exc, tb):
        self.stop()
        return False
